function ProfilePage() {
  const [tab, setTab] = useState('Posts');
  const [hire, setHire] = useState(false);
  const [editOpen, setEditOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);
  const [profileError, setProfileError] = useState('');
  const [avatarFile, setAvatarFile] = useState<File | null>(null);
  const { user, logout, updateProfile, uploadAvatar } = useAuth();
  const profile = user?.profile;
  const displayName = profile?.full_name || user?.email?.split('@')[0] || 'OLANET member';
  const initials = displayName.split(' ').map((part) => part[0]).join('').slice(0, 2).toUpperCase();
  const [form, setForm] = useState({
    username: profile?.username ?? '',
    fullName: profile?.full_name ?? '',
    bio: profile?.bio ?? '',
  });

  useEffect(() => {
    setForm({
      username: profile?.username ?? '',
      fullName: profile?.full_name ?? '',
      bio: profile?.bio ?? '',
    });
  }, [profile?.id, profile?.username, profile?.full_name, profile?.bio]);

  const openEditor = () => {
    setProfileError('');
    setSaved(false);
    setAvatarFile(null);
    setEditOpen(true);
  };

  const saveProfile = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setSaving(true);
    setProfileError('');
    setSaved(false);
    try {
      await updateProfile({
        username: form.username.trim() || null,
        full_name: form.fullName.trim() || null,
        bio: form.bio.trim() || null,
      });
      if (avatarFile) await uploadAvatar(avatarFile);
      setAvatarFile(null);
      setEditOpen(false);
      setSaved(true);
    } catch (error) {
      setProfileError(error instanceof Error ? error.message : 'Unable to save your profile.');
    } finally {
      setSaving(false);
    }
  };

  return <div className="page-enter mx-auto max-w-5xl">
    <div className="overflow-hidden rounded-[24px] border border-[#dfd2c0] bg-[#fffaf1]">
      <div className="soft-grid h-36 bg-gradient-to-r from-[#d8e8df] via-[#e9d6b9] to-[#d9e8e6]" />
      <div className="px-5 pb-6 sm:px-8">
        <div className="-mt-10 flex flex-col justify-between gap-4 sm:flex-row sm:items-end">
          <button type="button" data-testid="button-profile-avatar" aria-label="Edit profile picture" onClick={openEditor} className="rounded-full text-left outline-none focus:ring-2 focus:ring-[#2f817d]">
            <Avatar initials={initials} color="bg-[#e8c17a]" size="lg" src={profile?.avatar_url} />
          </button>
          <div className="flex flex-wrap gap-2">
            <Button variant="outline" icon={Settings2} onClick={openEditor}>Edit profile</Button>
            <Button onClick={() => setHire((v) => !v)} icon={hire ? Check : BriefcaseBusiness}>{hire ? 'Hire Me is on' : 'Hire Me'}</Button>
            <Button variant="ghost" onClick={() => void logout()} icon={LogOut}>Log out</Button>
          </div>
        </div>
        <div className="mt-4">
          <h2 className="display text-3xl font-bold">{displayName}</h2>
          <p className="mt-1 text-sm text-[#527075]">{profile?.username ? `@${profile.username} · ` : ''}{user?.email ?? 'Lagos, Nigeria'}</p>
          <p className="mt-4 max-w-2xl text-sm leading-6 text-[#527075]">{profile?.bio || 'Learning the trade one panel, diagram and honest question at a time. Add a short bio to tell people what you are building.'}</p>
          {saved && <p role="status" className="mt-3 text-xs font-bold text-[#2f817d]">Profile saved successfully.</p>}
          <div className="mt-4 flex flex-wrap gap-2"><Chip active>Electrical wiring</Chip><Chip>Solar basics</Chip><Chip>AutoCAD</Chip><Chip>Open to work</Chip></div>
          <div className="mt-6 flex gap-7 border-t border-[#eadfce] pt-5"><Stat value="248" label="helpful votes" /><Stat value="36" label="connections" /><Stat value="04" label="courses" /></div>
        </div>
      </div>
      <div className="flex gap-1 border-t border-[#eadfce] px-4 pt-2 sm:px-8">{['Posts', 'Skills & services', 'Courses', 'Certificates'].map((x) => <button data-testid={`tab-profile-${x.toLowerCase().replaceAll(' ', '-')}`} key={x} onClick={() => setTab(x)} className={`border-b-2 px-3 py-3 text-xs font-bold sm:px-4 sm:text-sm ${tab === x ? 'border-[#2f817d] text-[#2f817d]' : 'border-transparent text-[#789093]'}`}>{x}</button>)}</div>
    </div>
    <div className="mt-5">
      {tab === 'Posts' && <div className="space-y-4"><PostCard post={{ ...initialPosts[1], id: 301, ...people.you, name: displayName, initials, time: '3 days ago', text: 'Documenting my first clean distribution board labelling pass. Small details, safer work.', tag: 'My field notes' }} onLike={() => undefined} onComment={() => undefined} /></div>}
      {tab === 'Skills & services' && <div className="grid gap-4 sm:grid-cols-2"><ProfileBlock icon={Wrench} title="Services" items={['Residential wiring checks', 'Basic solar setup', 'Circuit tracing']} /><ProfileBlock icon={ShieldCheck} title="Trust signals" items={['Verified learning profile', '3 community recommendations', 'Available for Lagos jobs']} /></div>}
      {tab === 'Courses' && <div className="grid gap-4 sm:grid-cols-2"><ProfileBlock icon={Play} title="Learning in progress" items={['Solar Installation Foundations · 68%', 'The Trusted Repair Business · 32%']} /><ProfileBlock icon={Target} title="Next goal" items={['Complete protection devices lesson', 'Share one wiring diagram']} /></div>}
      {tab === 'Certificates' && <div className="grid gap-4 sm:grid-cols-2"><ProfileBlock icon={Award} title="Earned certificates" items={['Electrical Safety Basics', 'Introduction to Solar Systems']} /><EmptyState icon={Award} title="One more is close" text="Complete your current course to unlock a new shareable certificate." action="View courses" onAction={() => setTab('Courses')} /></div>}
    </div>
    {editOpen && <Modal title="Edit your profile" onClose={() => { if (!saving) setEditOpen(false); }}>
      <form onSubmit={saveProfile} className="space-y-4">
        <div className="flex items-center gap-3 rounded-2xl bg-[#f6eddf] p-3">
          <Avatar initials={initials} color="bg-[#e8c17a]" size="lg" src={profile?.avatar_url} />
          <div className="min-w-0 flex-1"><p className="text-sm font-bold">Profile picture</p><p className="mt-1 text-xs text-[#789093]">JPG, PNG, or WebP up to 5 MB.</p>{avatarFile && <p className="mt-1 truncate text-xs font-bold text-[#2f817d]">{avatarFile.name}</p>}</div>
          <label className="cursor-pointer rounded-xl bg-[#1d4348] px-3 py-2 text-xs font-bold text-[#fffaf1] hover:bg-[#28545a]">Choose<input data-testid="input-profile-picture" type="file" accept="image/jpeg,image/png,image/webp" className="hidden" onChange={(event) => setAvatarFile(event.target.files?.[0] ?? null)} /></label>
        </div>
        <label className="block text-xs font-bold text-[#527075]">Username<input data-testid="input-profile-username" value={form.username} onChange={(event) => setForm((current) => ({ ...current, username: event.target.value }))} placeholder="e.g. tobi_builds" className="mt-2 w-full rounded-xl border border-[#dfd2c0] bg-[#f8f2e8] px-3 py-3 text-sm font-normal outline-none focus:border-[#2f817d]" /></label>
        <label className="block text-xs font-bold text-[#527075]">Full name<input data-testid="input-profile-full-name" value={form.fullName} onChange={(event) => setForm((current) => ({ ...current, fullName: event.target.value }))} placeholder="Your name" className="mt-2 w-full rounded-xl border border-[#dfd2c0] bg-[#f8f2e8] px-3 py-3 text-sm font-normal outline-none focus:border-[#2f817d]" /></label>
        <label className="block text-xs font-bold text-[#527075]">Bio<textarea data-testid="input-profile-bio" value={form.bio} onChange={(event) => setForm((current) => ({ ...current, bio: event.target.value }))} placeholder="What are you learning or building?" rows={4} className="mt-2 w-full resize-none rounded-xl border border-[#dfd2c0] bg-[#f8f2e8] px-3 py-3 text-sm font-normal leading-6 outline-none focus:border-[#2f817d]" /></label>
        {profileError && <div role="alert" data-testid="text-profile-error" className="rounded-xl border border-[#e6b8ad] bg-[#fbe8e3] p-3 text-xs leading-5 text-[#9b4036]">{profileError}</div>}
        <div className="flex justify-end gap-2 pt-1"><Button type="button" variant="ghost" onClick={() => setEditOpen(false)} disabled={saving}>Cancel</Button><Button type="submit" disabled={saving}>{saving ? 'Saving…' : 'Save profile'}</Button></div>
      </form>
    </Modal>}
  </div>;
}
function ProfileBlock({ icon: Icon, title, items }: { icon: LucideIcon; title: string; items: string[] }) { return <div className="rounded-2xl border border-[#dfd2c0] bg-[#fffaf1] p-5"><div className="mb-4 flex items-center gap-2"><div className="rounded-xl bg-[#e5f0e9] p-2 text-[#2f817d]"><Icon size={17} /></div><h3 className="display text-xl font-bold">{title}</h3></div><div className="space-y-3">{items.map((item) => <div key={item} className="flex items-center gap-2 text-sm text-[#527075]"><Check size={15} className="text-[#2f817d]" />{item}</div>)}</div></div>; }

function AppRouter() {
  return <Switch><Route path="/" component={HomePage} /><Route path="/circles" component={CirclesPage} /><Route path="/circles/:id" component={CircleDetailPage} /><Route path="/snap-solve" component={SnapSolvePage} /><Route path="/tools" component={ToolsPage} /><Route path="/videos" component={VideosPage} /><Route path="/jobs" component={JobsPage} /><Route path="/courses" component={CoursesPage} /><Route path="/courses/:id" component={CourseDetailPage} /><Route path="/messages" component={MessagesPage} /><Route path="/notifications" component={NotificationsPage} /><Route path="/profile" component={ProfilePage} /><Route component={HomePage} /></Switch>;
}

function RoutedErrorBoundary({ children }: { children: ReactNode }) { const [location] = useLocation(); return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>; }
function AuthenticatedApp() { const { status } = useAuth(); if (status === 'loading') return <div className="flex min-h-[100dvh] items-center justify-center bg-[#f8f2e8]"><div className="display text-2xl font-bold text-[#1d4348]">Opening your workshop…</div></div>; if (status === 'unauthenticated') return <AuthScreen />; return <WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><AppShell><RoutedErrorBoundary><AppRouter /></RoutedErrorBoundary></AppShell></WouterRouter>; }
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><AuthProvider><AuthenticatedApp /></AuthProvider><Toaster /></TooltipProvider></QueryClientProvider>; }

export default App;